        readonly Random _rng;
        readonly Dictionary<string, string> _last = new Dictionary<string, string>();
        readonly Dictionary<string, List<string>> _deck = new Dictionary<string, List<string>>();

        public Speech(Random rng = null) { _rng = rng ?? new Random(); }

        /// <summary>비욘의 호위·전투 대사는 전용 묶음, 나머지 공통 작업 대사는 라그나 묶음을 쓴다.</summary>
        static Dictionary<string, string[]> SetOf(Personality p) => Lines[p == Personality.Floki ? 1 : p == Personality.Guard ? 2 : 0];

        static string[] GetOptions(Personality p, string key)
        {
            if (SetOf(p).TryGetValue(key, out var lines)) return lines;
            return p == Personality.Guard && Lines[0].TryGetValue(key, out lines) ? lines : null;
        }

        public static bool Has(Personality p, string key) => GetOptions(p, key) != null;

        /// <summary>그 키의 대사 줄 전부(시험이 들은 말과 맞춰 볼 때). 없으면 빈 배열.</summary>
        public static string[] Options(Personality p, string key) => GetOptions(p, key) ?? new string[0];

        /// <summary>대사 하나. 상황마다 카드 섞기: 그 상황 줄을 다 쓸 때까지 같은 줄을 다시 안 내고, 새로 섞은 첫 줄도 바로 전 줄과 다르게(사용자 10-29).
        /// 없는 키면 키 이름을 그대로 돌려준다.</summary>
        public string Say(Personality p, string key, IDictionary<string, string> args = null)
        {
            var options = GetOptions(p, key);
            if (options == null || options.Length == 0) return key;
            string memo = (int)p + "/" + key;
            _last.TryGetValue(memo, out var last);
            if (!_deck.TryGetValue(memo, out var deck) || deck.Count == 0)
            {
                deck = new List<string>(options);
                for (int i = deck.Count - 1; i > 0; i--)
                {
                    int j = _rng.Next(i + 1);
                    var t = deck[i]; deck[i] = deck[j]; deck[j] = t;
                }
                if (deck.Count > 1 && deck[deck.Count - 1] == last)
                {
                    var t = deck[0]; deck[0] = deck[deck.Count - 1]; deck[deck.Count - 1] = t;
                }
                _deck[memo] = deck;
            }
            string line = deck[deck.Count - 1];
            deck.RemoveAt(deck.Count - 1);
            _last[memo] = line;
            if (args != null)
                foreach (var kv in args)
                {
                    line = WithJosa(line, kv.Key, kv.Value);
                    line = line.Replace("{" + kv.Key + "}", kv.Value);
                }
            return line;
        }

        /// <summary>"{key|는}" → 값 + 받침에 맞는 조사.</summary>
        static string WithJosa(string line, string key, string value)
        {
            string open = "{" + key + "|";
            int i;
            while ((i = line.IndexOf(open, StringComparison.Ordinal)) >= 0)
            {
                int end = line.IndexOf('}', i);
                if (end < 0) break;
                string josa = line.Substring(i + open.Length, end - i - open.Length);
                line = line.Substring(0, i) + value + Josa.For(value, josa) + line.Substring(end + 1);
            }
            return line;
        }
    }
